/**
 * Typed loaders for ArUco dictionaries and AprilTag families.
 * JSON files are generated by scripts/gen-dicts.py and scripts/gen-apriltag.mjs.
 */

export interface ArUcoDict {
  name: string;
  markerSize: number;
  maxCorrectionBits: number;
  count: number;
  bits: string[];
}

export interface AprilTagFamily {
  name: string;
  nbits: number;
  d: number;
  minHamming: number;
  count: number;
  codes: string[];
  /** Bit-to-cell column mapping (from apriltag C source / OpenCV). */
  bit_x?: number[];
  /** Bit-to-cell row mapping (from apriltag C source / OpenCV). */
  bit_y?: number[];
}

// Static imports for ArUco dictionaries
import DICT_4X4_50 from './DICT_4X4_50.json';
import DICT_5X5_100 from './DICT_5X5_100.json';
import DICT_6X6_250 from './DICT_6X6_250.json';
import DICT_7X7_1000 from './DICT_7X7_1000.json';
import DICT_ARUCO_ORIGINAL from './DICT_ARUCO_ORIGINAL.json';
import DICT_ARUCO_MIP_36h12 from './DICT_ARUCO_MIP_36h12.json';

// Static imports for AprilTag families
import AT_16h5 from './apriltag-16h5.json';
import AT_25h9 from './apriltag-25h9.json';
import AT_36h11 from './apriltag-36h11.json';
// 41h12 and 52h13 removed: bit_x/bit_y layouts not yet derived, renders incorrect.
// import AT_41h12 from './apriltag-41h12.json';
// import AT_52h13 from './apriltag-52h13.json';

const ARUCO_DICTS: Record<string, ArUcoDict> = {
  DICT_4X4_50: DICT_4X4_50 as unknown as ArUcoDict,
  DICT_5X5_100: DICT_5X5_100 as unknown as ArUcoDict,
  DICT_6X6_250: DICT_6X6_250 as unknown as ArUcoDict,
  DICT_7X7_1000: DICT_7X7_1000 as unknown as ArUcoDict,
  DICT_ARUCO_ORIGINAL: DICT_ARUCO_ORIGINAL as unknown as ArUcoDict,
  DICT_ARUCO_MIP_36h12: DICT_ARUCO_MIP_36h12 as unknown as ArUcoDict,
};

export function getArUcoDict(name: string): ArUcoDict | undefined {
  return ARUCO_DICTS[name];
}

export function arucoDictNames(): string[] {
  return Object.keys(ARUCO_DICTS);
}

/**
 * Decode hex-encoded marker bytes into a 2D bit grid (0/1).
 * Returns markerSize x markerSize array of 0|1.
 */
export function decodeMarkerBits(hex: string, markerSize: number): number[][] {
  const bytes: number[] = [];
  for (let i = 0; i < hex.length; i += 2) {
    bytes.push(parseInt(hex.substring(i, i + 2), 16));
  }
  const bytesPerRow = Math.ceil(markerSize / 8);
  const grid: number[][] = [];
  for (let r = 0; r < markerSize; r++) {
    const row: number[] = [];
    for (let c = 0; c < markerSize; c++) {
      const byteIdx = r * bytesPerRow + Math.floor(c / 8);
      const bitIdx = 7 - (c % 8);
      row.push((bytes[byteIdx] >> bitIdx) & 1);
    }
    grid.push(row);
  }
  return grid;
}

const APRILTAG_FAMILIES: Record<string, AprilTagFamily> = {
  '16h5': AT_16h5 as unknown as AprilTagFamily,
  '25h9': AT_25h9 as unknown as AprilTagFamily,
  '36h11': AT_36h11 as unknown as AprilTagFamily,
  // 41h12 and 52h13 removed — bit_x/bit_y layouts not yet derived.
};

export function getAprilFamily(name: string): AprilTagFamily | undefined {
  return APRILTAG_FAMILIES[name];
}

export function aprilFamilyNames(): string[] {
  return Object.keys(APRILTAG_FAMILIES);
}

/**
 * Decode an AprilTag code (hex uint64) into a d x d bit grid.
 *
 * AprilTag families use a non-row-major spiral bit layout defined by
 * per-family bit_x/bit_y arrays from the apriltag C source.  If the
 * family provides these arrays, they are used; otherwise falls back to
 * row-major (only valid for families whose layout happens to be row-major,
 * which in practice is none of the standard families).
 */
export function decodeAprilBits(hex: string, d: number, bit_x?: number[], bit_y?: number[]): number[][] {
  const code = BigInt('0x' + hex);
  const grid: number[][] = Array.from({ length: d }, () => Array(d).fill(0));

  if (bit_x && bit_y) {
    const nbits = bit_x.length;
    for (let b = 0; b < nbits; b++) {
      const x = bit_x[b];
      const y = bit_y[b];
      if (x >= 0 && x < d && y >= 0 && y < d) {
        grid[y][x] = Number((code >> BigInt(b)) & 1n);
      }
    }
  } else {
    // Fallback: row-major (incorrect for standard families, kept for compat)
    const nbits = d * d;
    for (let b = 0; b < nbits; b++) {
      const r = Math.floor(b / d);
      const c = b % d;
      grid[r][c] = Number((code >> BigInt(b)) & 1n);
    }
  }
  return grid;
}
